@Component("insuredObject-handler")
@ProcessingGroup("insuredObject-processing-group")
public class InsuredObjectEventHandler {
	
	// core constructor
	InsuredObjectEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateInsuredObjectEvent
     */
    @EventHandler
    public void handle( CreateInsuredObjectEvent event) {
        entityManager.persist(new InsuredObject(event.getInsuredObjectId(), event.getDescription(), event.getSerialOrId(), event.getPrimaryAddress(), event.getPolicy(), event.getCoverages(), event.getObjectType()));
    }

    /*
     * @param	event UpdateInsuredObjectEvent
     */
    @EventHandler
    public InsuredObject handle( UpdateInsuredObjectEvent event) {
    	entityManager.merge(new InsuredObject(event.getInsuredObjectId(), event.getDescription(), event.getSerialOrId(), event.getPrimaryAddress(), event.getPolicy(), event.getCoverages(), event.getObjectType()));
    }
    
    /*
     * @param	event DeleteInsuredObjectEvent
     */
    @EventHandler
    public void on( DeleteInsuredObjectEvent event) {
    	InsuredObject entity = new InsuredObject();
   
    	// ------------------------------------------
    	// apply the InsuredObjectId
    	// ------------------------------------------
    	entity.setInsuredObjectId( event.getInsuredObjectId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final InsuredObjectRepository insuredObjectEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(InsuredObjectEventHandler.class.getName());

}
